(() => {
  'use strict';

  const SELECTOR = '[data-ice-standings]';

  class IceStandings {
    constructor(root) {
      this.root = root;
      this.button = root.querySelector('[data-ice-switch]');
      this.main = root.querySelector('[data-ice-main]');
      this.rail = root.querySelector('[data-ice-rail]');
      this.tablePages = Array.from(root.querySelectorAll('[data-ice-page]'));
      this.railPages = Array.from(root.querySelectorAll('[data-ice-rail-page]'));
      this.activePage = 0;
      this.locked = false;

      if (!this.button || this.tablePages.length < 2 || this.railPages.length < 2) {
        return;
      }

      this.button.addEventListener('click', () => this.switchPage());
      this.updateLabel();
    }

    switchPage() {
      if (this.locked) {
        return;
      }

      this.locked = true;
      this.root.classList.add('is-switching');

      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const delay = reduceMotion ? 0 : 130;

      window.setTimeout(() => {
        this.activePage = (this.activePage + 1) % this.tablePages.length;
        this.showOnly(this.tablePages, this.activePage);
        this.showOnly(this.railPages, this.activePage);
        this.root.classList.toggle('is-page-2', this.activePage === 1);
        this.updateLabel();

        window.requestAnimationFrame(() => {
          this.root.classList.remove('is-switching');
          window.setTimeout(() => {
            this.locked = false;
          }, reduceMotion ? 0 : 170);
        });
      }, delay);
    }

    showOnly(elements, activeIndex) {
      elements.forEach((element, index) => {
        element.hidden = index !== activeIndex;
      });
    }

    updateLabel() {
      const label = this.root.getAttribute(`data-label-page-${this.activePage}`);

      if (label) {
        this.button.setAttribute('aria-label', label);
      }
    }
  }

  const initialise = (scope = document) => {
    scope.querySelectorAll(SELECTOR).forEach((root) => {
      if (root.dataset.iceStandingsReady === 'true') {
        return;
      }

      root.dataset.iceStandingsReady = 'true';
      new IceStandings(root);
    });
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => initialise(), { once: true });
  } else {
    initialise();
  }

  document.addEventListener('joomla:updated', (event) => {
    initialise(event.target instanceof Element ? event.target : document);
  });
})();
